cd /tmp/pw-check && cat > devcheck.mjs <<'EOF'
import {chromium} from 'playwright';
const browser = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
const context = await browser.newContext({viewport: {width: 1280, height: 800}, locale: 'ru-RU'});
await context.route((url) => url.hostname !== '127.0.0.1', (route) => route.abort());
const page = await context.newPage();
const msgs = [];
page.on('pageerror', (e) => msgs.push('pageerror: ' + e.message));
page.on('console', (m) => { if (['error', 'warning'].includes(m.type())) msgs.push(m.type() + ': ' + m.text().slice(0, 160)); });
await page.goto('http://127.0.0.1:5179/', {waitUntil: 'load', timeout: 30000});
await page.waitForSelector('.cpu-chart .uplot canvas', {timeout: 15000});
await page.waitForTimeout(5000);
const count = () => page.locator('.cpu-chart .uplot').count();
const out = {devUplotAfterStrictMount: await count()};
await page.emulateMedia({colorScheme: 'dark'});
await page.waitForTimeout(800);
out.afterDarkSwitch = await count();
await page.emulateMedia({colorScheme: 'light'});
await page.waitForTimeout(800);
out.afterLightSwitch = await count();
await page.waitForTimeout(4000);
out.canvasSize = await page.evaluate(() => { const c = document.querySelector('.cpu-chart canvas'); return [c.width, c.height]; });
out.messages = msgs;
console.log(JSON.stringify(out, null, 1));
await browser.close();
EOF
export LD_LIBRARY_PATH=$(find /tmp/chrome-libs/root -name "*.so*" -printf "%h\n" | sort -u | paste -sd:) FONTCONFIG_FILE=/tmp/chrome-libs/fonts.conf && timeout 150 node devcheck.mjs 2>&1 | head -40
